class DListNode {
  constructor(public key: string, public value: any, public prev: DListNode | null = null, public next: DListNode | null = null) {}
}

export class LRUCache {
  private map = new Map<string, DListNode>();
  private head: DListNode = new DListNode("", null);
  private tail: DListNode = new DListNode("", null);

  constructor(private capacity: number) {
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  get(key: string): any {
    const node = this.map.get(key);
    if (!node) return null;
    this.moveToHead(node); // Promoted to MRU
    return node.value;
  }

  private moveToHead(node: DListNode) {
    // Detach
    node.prev!.next = node.next;
    node.next!.prev = node.prev;
    // Attach behind head
    node.next = this.head.next;
    node.prev = this.head;
    this.head.next!.prev = node;
    this.head.next = node;
  }
}
